/*
  ===== CAL.COM SETUP =====
  1. Create a free account at cal.com and connect your Google Calendar
     (Settings -> Apps -> Google Calendar).
  2. Create two event types:
       - "Free Inspection & Quote"  e.g. slug: free-inspection
       - "Seal Service"             e.g. slug: seal-service
  3. Replace CAL_USERNAME below with your cal.com username, and the two
     slugs below with your real event type slugs.
  Every booking made through the embed below will appear on your Google
  Calendar automatically -- no other setup needed.
*/
const CAL_USERNAME = "pestseal";
const CAL_EVENT_SLUGS = {
  inspection: "inspectionquote",
  seal: "sealservice",
};

// Loads Cal.com's official embed script once and mounts an inline
// scheduler for the given namespace/event slug into #cal-inline-<namespace>.
function loadCalEmbed(namespace, slug, brandColor, onBooked) {
  (function (C, A, L) {
    let p = function (a, ar) { a.q.push(ar); };
    let d = C.document;
    C.Cal = C.Cal || function () {
      let cal = C.Cal;
      let ar = arguments;
      if (!cal.loaded) {
        cal.ns = {};
        cal.q = cal.q || [];
        d.head.appendChild(d.createElement("script")).src = A;
        cal.loaded = true;
      }
      if (ar[0] === L) {
        const api = function () { p(api, arguments); };
        const ns = ar[1];
        api.q = api.q || [];
        if (typeof ns === "string") {
          cal.ns[ns] = cal.ns[ns] || api;
          p(cal.ns[ns], ar);
          p(cal, ["initNamespace", ns]);
        } else p(cal, ar);
        return;
      }
      p(cal, ar);
    };
  })(window, "https://app.cal.com/embed/embed.js", "init");

  window.Cal("init", namespace, { origin: "https://cal.com" });
  window.Cal.ns[namespace]("inline", {
    elementOrSelector: `#cal-inline-${namespace}`,
    config: { layout: "month_view" },
    calLink: `${CAL_USERNAME}/${slug}`,
  });
  window.Cal.ns[namespace]("ui", {
    theme: "light",
    styles: { branding: { brandColor } },
    hideEventTypeDetails: false,
    layout: "month_view",
  });
  window.Cal.ns[namespace]("on", {
    action: "bookingSuccessful",
    callback: onBooked,
  });
}

