function StepDot({ index, active, done, label }) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 8, flex: 1 }}>
      <div
        style={{
          width: 26,
          height: 26,
          borderRadius: "50%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          fontFamily: "Fredoka, sans-serif",
          fontSize: 13,
          fontWeight: 600,
          flexShrink: 0,
          background: done ? COLORS.amber1 : active ? COLORS.ink : "transparent",
          color: done || active ? "#fff" : COLORS.stoneDeep,
          border: `2px solid ${done ? COLORS.amber1 : active ? COLORS.ink : COLORS.stone}`,
        }}
      >
        {done ? <CheckCircle2 size={15} /> : index}
      </div>
      <span
        style={{
          fontSize: 13,
          fontFamily: "Work Sans, sans-serif",
          fontWeight: 600,
          color: active || done ? COLORS.ink : COLORS.stoneDeep,
        }}
      >
        {label}
      </span>
    </div>
  );
}

